// build-game: write the GDevelop project of "Little Ember" (GDevelop BIG Game Jam #10, theme "Keep It Alive").
// For MV2 of Munim, Inc. Made with AI agents (Anthropic Claude). Apache-2.0.
//
//   node build-game.mjs <out dir> <example project.json> [more example .json ...]
//
// Writes <out dir>/game.json plus every image (PNG) and sound (WAV) it uses, all generated by art.mjs,
// and <out dir>/cover.png (the itch.io cover; not used by the game). Uses MV2's open-source gdwrite
// (Apache-2.0, published before the jam) to write the project; the example projects only supply
// GDevelop's own object/scene templates.

import fs from "node:fs";
import path from "node:path";
import { loadTemplates, textObject, spriteObject, imageResource, audioResource, instance, jsEvent, buildProject } from "./gdwrite.mjs";
import { makeImages, makeSounds, makeCover } from "./art.mjs";

const [outDir, ...examples] = process.argv.slice(2);
if (!outDir || !examples.length) { console.error("usage: node build-game.mjs <out dir> <example.json> [...]"); process.exit(64); }
const log = (...a) => console.log("[build-game]", ...a);
const t = loadTemplates(examples.map((f) => JSON.parse(fs.readFileSync(f, "utf8"))));
fs.mkdirSync(outDir, { recursive: true });

const images = makeImages(), sounds = makeSounds();
for (const [f, buf] of Object.entries({ ...images, ...sounds })) fs.writeFileSync(path.join(outDir, f), buf);
fs.writeFileSync(path.join(outDir, "cover.png"), makeCover());
const pngSize = (b) => [b.readUInt32BE(16), b.readUInt32BE(20)];
log("images:", Object.entries(images).map(([f, b]) => f + " " + pngSize(b).join("x")).join(", "));
log("sounds:", Object.entries(sounds).map(([f, b]) => f + " " + (b.length / 44100).toFixed(1) + "s").join(", "));

const sprites = [
  ["SkyNight", "sky-night.png"], ["SkyDawn", "sky-dawn.png"], ["Land", "land.png"], ["Dark", "dark.png"],
  ["Eyes", "eyes.png"], ["Glow", "glow.png"], ["Hearth", "hearth.png"], ["FlameA", "flame-a.png"], ["FlameB", "flame-b.png"],
  ["Face", "face.png"], ["FaceSad", "face-sad.png"], ["FaceBlink", "face-blink.png"], ["Snow", "snow.png"], ["Clump", "clump.png"],
  ["Gust", "gust.png"], ["Twig", "twig.png"], ["Cone", "cone.png"], ["Spark", "spark.png"], ["Puff", "puff.png"],
  ["BarBack", "bar-back.png"], ["BarFill", "bar-fill.png"], ["TitleImg", "title.png"],
];
const cream = [255, 240, 214];
const texts = [
  ["Clock", { text: "9:00 PM", size: 30, color: cream }], ["Score", { text: "Score 0", size: 30, color: cream }],
  ["Warm", { text: "WARMTH", size: 20, color: cream }], ["Hint", { text: "", size: 30, color: [255, 228, 170] }],
  ["Sub", { text: "", size: 32, color: [236, 240, 255] }], ["Start", { text: "", size: 32, color: [255, 214, 120] }],
  ["Help", { text: "", size: 24, color: [214, 224, 255] }], ["Big", { text: "", size: 54, color: [255, 236, 190] }],
  ["Best", { text: "", size: 26, color: [255, 214, 120] }], ["Credit", { text: "", size: 18, color: [200, 206, 236] }],
  ["Float", { text: "", size: 30, color: [255, 214, 120] }],
];

let id = 1;
const inst = (name, x, y, z, size) => instance(t, name, x, y, id++, z, size || null);
const instances = [
  inst("SkyNight", 0, 0, -10), inst("SkyDawn", 0, 0, -9), inst("Land", 0, 0, -8),
  inst("Dark", 0, 0, -7, { width: 1280, height: 720 }),
  inst("Eyes", 170, 524, -6), inst("Eyes", 1074, 518, -6), inst("Eyes", 92, 560, -6), inst("Eyes", 1150, 566, -6),
  inst("Glow", 0, 0, -5), inst("Hearth", 560, 534, -4),
  inst("FlameA", 590, 430, 5), inst("FlameB", 590, 430, 5), inst("Face", 612, 500, 6), inst("FaceSad", 612, 500, 6), inst("FaceBlink", 612, 500, 6),
  inst("BarBack", 476, 18, 30), inst("BarFill", 480, 22, 31), inst("TitleImg", 340, 100, 40),
  ...["Clock", "Score", "Warm", "Hint", "Sub", "Start", "Help", "Big", "Best", "Credit"].map((n) => inst(n, 0, -200, 45)),
];

const code = fs.readFileSync(new URL("./game-code.js", import.meta.url), "utf8");
const proj = buildProject(t, {
  name: "Little Ember", packageName: "com.munimtechnologies.littleember", width: 1280, height: 720, bg: [8, 12, 34],
  resources: [...Object.keys(images).map((f) => imageResource(t, f)), ...Object.keys(sounds).map((f) => audioResource(t, f))],
  objects: [...sprites.map(([n, f]) => spriteObject(t, n, f)), ...texts.map(([n, o]) => textObject(t, n, o))],
  instances,
  events: [jsEvent(code)],
});

// A fixed 1280x720 game, letterboxed on other screen shapes, so scene coordinates never shift.
const P = proj.properties;
const set = (k, v) => { if (k in P) P[k] = v; };
set("sizeOnStartupMode", "");
set("adaptGameResolutionAtRuntime", false);
set("orientation", "landscape");
set("version", "1.0.0");
P.author = "MV2 of Munim, Inc.";
P.description = "Keep the little ember alive until dawn. Made for GDevelop BIG Game Jam #10 (theme: Keep It Alive) by MV2 of Munim, Inc., with AI agents (Anthropic Claude).";
log("properties:", JSON.stringify({ sizeOnStartupMode: P.sizeOnStartupMode, adapt: P.adaptGameResolutionAtRuntime, scaleMode: P.scaleMode,
  orientation: P.orientation, pixelsRounding: P.pixelsRounding, fps: [P.minFPS, P.maxFPS], loadingScreen: P.loadingScreen ? Object.keys(P.loadingScreen) : null }));

fs.writeFileSync(path.join(outDir, "game.json"), JSON.stringify(proj, null, 2));
log("wrote", path.join(outDir, "game.json"), "| objects:", proj.layouts[0].objects.length, "| instances:", instances.length,
  "| resources:", (proj.resources.resources || proj.resources).length, "| code chars:", code.length);
